package org.jsoup.nodes;

import java.io.*;
import java.math.*;
import java.net.MalformedURLException;
import java.net.URL;
import java.util.*;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import org.htmlcleaner.TagNode;
import org.jsoup.helper.StringUtil;
import org.jsoup.helper.Validate;
import org.jsoup.parser.Parser;
import org.jsoup.select.NodeTraversor;
import org.jsoup.select.NodeVisitor;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

public class Node_siblingNodes_TriageGen1Test {

    private Node parentNode;
    private Node childNode1;
    private Node childNode2;
    private Node childNode3;

    @Before
    public void setUp() {
        parentNode = new TagNode("div", null, null);
        childNode1 = new TagNode("p", null, null);
        childNode2 = new TagNode("span", null, null);
        childNode3 = new TagNode("a", null, null);

        parentNode.addChildren(childNode1, childNode2, childNode3);
    }

    @Test
    public void testSiblingNodes_NoParent() {
        Node orphanNode = new TagNode("p", null, null);
        List<Node> siblings = orphanNode.siblingNodes();
        assertEquals(0, siblings.size());
    }

    @Test
    public void testSiblingNodes_OneChild() {
        List<Node> siblings = childNode1.siblingNodes();
        assertEquals(2, siblings.size());
        assertTrue(siblings.contains(childNode2));
        assertTrue(siblings.contains(childNode3));
    }

    @Test
    public void testSiblingNodes_MultipleChildren() {
        List<Node> siblings = childNode2.siblingNodes();
        assertEquals(2, siblings.size());
        assertTrue(siblings.contains(childNode1));
        assertTrue(siblings.contains(childNode3));
    }

    @Test
    public void testSiblingNodes_SingleChild() {
        Node singleChildParent = new TagNode("div", null, null);
        Node singleChild = new TagNode("p", null, null);
        singleChildParent.addChildren(singleChild);

        List<Node> siblings = singleChild.siblingNodes();
        assertEquals(0, siblings.size());
    }

    @Test
    public void testSiblingNodes_NoChildren() {
        List<Node> siblings = parentNode.siblingNodes();
        assertEquals(0, siblings.size());
    }

    @Test
    public void testSiblingNodes_SelfAsSibling() {
        parentNode.addChildren(parentNode);
        List<Node> siblings = parentNode.siblingNodes();
        assertEquals(1, siblings.size());
        assertTrue(siblings.contains(parentNode));
    }

    @Test
    public void testSiblingNodes_NullParent() {
        Node nodeWithNullParent = new TagNode("p", null, null);
        nodeWithNullParent.setParentNode(null);
        List<Node> siblings = nodeWithNullParent.siblingNodes();
        assertEquals(0, siblings.size());
    }
}
